    m=re.search(r'\bstep:(\d+) - ',line)
    if not m: continue
    step=int(m[1]); fields={}
    for item in line[m.end():].split(' - '):
        key,sep,value=item.partition(':')
        if sep:
            try: fields[key]=float(value.strip())
