for lo,hi in ((1,50),(251,400)):
    samples=[rows[s][1] for s in range(lo,hi+1)]
    print('window',lo,hi,'zero_gradient_steps',sum(s['actor/grad_norm']==0 for s in samples),'mean', {k:sum(s[k] for s in samples)/len(samples) for k in ('critic/rewards/mean','response_length/mean','response_length/clip_ratio','actor/entropy','timing_s/step')})
print('unique_steps',len(rows)-1,'all_ppo_kl_zero',all(r[1].get('actor/ppo_kl',0)==0 for r in rows.values()),'max_grad_norm',max((r[1].get('actor/grad_norm',0),s) for s,r in rows.items()))
